import random
import statistics

def task_func(LETTERS):
    letters = list(dict.fromkeys(LETTERS)) if LETTERS is not None else []
    if not letters:
        return {}

    data = {
        letter: [random.randint(0, 100) for _ in range(random.randint(1, 10))]
        for letter in random.sample(letters, random.randint(1, len(letters)))
    }

    return dict(
        sorted(
            data.items(),
            key=lambda item: statistics.mean(item[1]),
            reverse=True
        )
    )
